import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().process();
    }

    void process() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] poly = new int[10];
        for (int i = 0; i < k; i++) {
            poly[in.nextInt()] = 1;
        }
        int[] res = new int[]{1};
        int exponent = n / 2;
        while (true) {
            if ((exponent & 1) == 1) {
                res = multiply(res, poly, MOD);
            }
            exponent >>= 1;
            if (exponent == 0) break;
            poly = multiply(poly, poly, MOD);
        }
        long total = 0;
        for (int val : res) {
            total = (total + (long)val * val) % MOD;
        }
        out.println(total);
        out.close();
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int required = a.length + b.length - 1;
        int size = 1;
        while (size < required) size <<= 1;

        double[] ar = new double[size];
        double[] ai = new double[size];
        for (int i = 0; i < a.length; i++) {
            long val = ((long)a[i] % mod + mod) % mod;
            ar[i] = val & 0x7FFF;
            ai[i] = val >>> 15;
        }

        transform(ar, ai, false);

        double[] br = new double[size];
        double[] bi = new double[size];
        if (a == b) {
            System.arraycopy(ar, 0, br, 0, size);
            System.arraycopy(ai, 0, bi, 0, size);
        } else {
            for (int i = 0; i < b.length; i++) {
                long val = ((long)b[i] % mod + mod) % mod;
                br[i] = val & 0x7FFF;
                bi[i] = val >>> 15;
            }
            transform(br, bi, false);
        }

        double[] cr = new double[size];
        double[] ci = new double[size];
        double scale = 0.25 / size;

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double A1r = ar[i] + ar[j];
            double A1i = ai[i] - ai[j];
            double A2r = ai[i] + ai[j];
            double A2i = ar[j] - ar[i];

            double B1r = (br[i] + br[j]) * scale;
            double B1i = (bi[i] - bi[j]) * scale;
            double B2r = (bi[i] + bi[j]) * scale;
            double B2i = (br[j] - br[i]) * scale;

            cr[i] = A1r * B1r - A1i * B1i - A2r * B2i - A2i * B2r;
            ci[i] = A1r * B1i + A1i * B1r + A2r * B2r - A2i * B2i;
        }

        transform(cr, ci, true);

        int[] result = new int[required];
        for (int i = 0; i < required; i++) {
            long realPart = Math.round(cr[i]);
            long imagPart = Math.round(ci[i]);
            result[i] = (int)((realPart + ((imagPart % mod) << 15)) % mod);
        }
        return result;
    }

    void transform(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            while ((j & bit) != 0) {
                j ^= bit;
                bit >>= 1;
            }
            j ^= bit;
            if (i < j) {
                double tmp = re[i]; re[i] = re[j]; re[j] = tmp;
                tmp = im[i]; im[i] = im[j]; im[j] = tmp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosTable = new double[half];
            double[] sinTable = new double[half];
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosTable[i] = Math.cos(i * angle);
                sinTable[i] = Math.sin(i * angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int k = 0; k < half; k++) {
                    double ur = re[i + k];
                    double ui = im[i + k];
                    double vr = re[i + k + half] * cosTable[k] - im[i + k + half] * sinTable[k];
                    double vi = re[i + k + half] * sinTable[k] + im[i + k + half] * cosTable[k];

                    re[i + k] = ur + vr;
                    im[i + k] = ui + vi;
                    re[i + k + half] = ur - vr;
                    im[i + k + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream input;
        private final byte[] bytes = new byte[1024];
        private int index, length;

        public InputReader(InputStream input) {
            this.input = input;
        }

        private int nextByte() {
            if (length == -1) throw new InputMismatchException();
            if (index >= length) {
                index = 0;
                try { length = input.read(bytes); } catch (IOException e) { throw new InputMismatchException(); }
                if (length <= 0) return -1;
            }
            return bytes[index++] & 0xFF;
        }

        public int nextInt() {
            int c = nextByte();
            while (c <= 32) c = nextByte();
            int sign = 1;
            if (c == '-') { sign = -1; c = nextByte(); }
            int num = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                num = num * 10 + c - '0';
                c = nextByte();
            }
            return num * sign;
        }
    }
}
